/**
 * Points program rules (docs/08-TOKENOMICS.md §5). Points reward real usage and are weighted by the
 * USDC fees a task actually paid (released milestones only), never by task count. Points are not a
 * promise of tokens; the airdrop allocation is decided separately and published.
 */

/** Points per 1 USDC of fees, for the client who paid them. */
export const CLIENT_POINTS_PER_USDC = 100n;
/** Points per 1 USDC of fees generated by a provider's accepted, paid work. */
export const PROVIDER_POINTS_PER_USDC = 50n;
/** Tasks paying less than this (USDC, decimal) earn no points: too cheap to be meaningful work. */
export const POINTS_MIN_TASK_USDC = "1";
/** Between the same client and provider, tasks after this many in 30 days earn a fifth. */
export const POINTS_REPEAT_PAIR_LIMIT = 5;
export const POINTS_REPEAT_PAIR_FACTOR_BPS = 2_000n;
/** At most this many points per user per day. */
export const POINTS_DAILY_CAP = 50_000;

export type PointsFlag = "self-dealing" | "below-minimum" | "repeat-pair" | "daily-cap";
